/bin/zsh -lc "python3 -c 'import json,re
for p in [\"lexicon/core.json\",\"lexicon/domains/software.json\"]:
 d=json.load(open(p)); print(p,list(d) if isinstance(d,dict) else \"list\")
 def walk(v):
  if isinstance(v,dict):
   if \"lemma\" in v:
    if re.search(\"가능|문제|권한|지원|갱신|접수|승인|검증|확정|보관|제외|삭제|백업|복원|권장|명목|오차|최대|간격|완료|수 있다|끝나다\",v[\"lemma\"]): print(json.dumps({k:v[k] for k in [\"id\",\"lemma\",\"sense_id\"] if k in v},ensure_ascii=False))
   else:
    for x in v.values(): walk(x)
  elif isinstance(v,list):
   for x in v: walk(x)
 walk(d)'"
